// Package ui — icons.go holds the UI's chrome icons: Lucide SVGs fetched
// via the icons MCP (set "lu", ISC license), tinted by currentColor, which
// nsgo's core.Icon draws with its style's Color.
package ui

import "github.com/nsgo-dev/nsgo/core"

// lucide wraps one fetched Lucide icon's markup.
func lucide(body string) *core.SVG {
	return core.MustParseSVG([]byte(
		`<svg xmlns="http://www.w3.org/2000/svg" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24">` +
			body + `</svg>`))
}

